    {
        "id": 27,
        "modulo": "Mercado de Capitais",
        "pergunta": "No  ano  de  1995  o  banco  de  investimentos  Barings,  o  mais  antigo  da\nInglaterra,  quebrou  devido  as  enormes  perdas,  US$  1,2  bilhões  decorrentes  de\nespeculações feitas por um dos seu operadores Nick Leeson. Ele apostava na alta do\níndice  da  bolsa  de  Tóquio  que,  entretanto,  teve  fortes  baixas.  A  partir  daí  os\nadministradores de bancos e de grandes empresas passaram a utilizar a métrica de risco\nconhecida como Value at Risk - VaR com o objetivo de conhecer e controlar os riscos de\nmercado. Considerando a análise de retornos esperados e riscos , ao avaliarem novo\nnegócio, os administradores de empresa ou instituição ﬁnanceira devem:",
        "opcoes": {
            "A": "Aprovar o negócio se o retorno esperado for alto e o novo VaR ﬁcar elevado.",
            "B": "Recusar o negócio se o retorno esperado for alto e o novo VaR ﬁcar baixo\n(situação de hedge).",
            "C": "Aprovar o negócio se o VaR ﬁcar mais baixo (situação de hedge),\nindependentemente do retorno esperado.",
            "D": "Aprovar o negócio se o retorno esperado for satisfatório e o novo VaR ﬁcar baixo\n(situação de hedge)",
        },
        "resposta_correta": "D",
        "explicacao": "A decisão de aprovação de um negócio deve considerar simultaneamente o retorno esperado e o risco associado, medido pelo Value at Risk (VaR), conforme princípios de gestão prudencial de riscos descritos na Resolução CMN 4.557/17 e práticas recomendadas pelo Banco Central. Um retorno satisfatório alinhado a um VaR baixo indica que o negócio agrega valor sem elevar excessivamente o risco de mercado, caracterizando uma situação de hedge que protege o portfólio. Portanto, a alternativa correta é aprovar o negócio quando o retorno esperado é satisfatório e o VaR diminui, refletindo controle eficiente do risco."
    },
