    {
        "id": 193,
        "modulo": "Mercado de Capitais",
        "pergunta": "Com relação aos programas de BDR, considere as aﬁrmativas abaixo:\nI – BDR Nível I: admissão à negociação em mercados organizados de valores mobiliários,\ndevendo  ocorrer  em  segmento  especíﬁco  ou  sob  codiﬁcação  exclusiva  para  BDR  Nível  I\nconforme  atribuído  pela  entidade  administradora  de  mercado  organizado de  valores\nmobiliários.\nII – BDR Nível II: admissão à negociação em mercados organizados de valores mobiliários.\nIII – BDR Nível III: admissão à negociação em mercados organizados de valores mobiliários.\nIV – BDR não patrocinado: somente é admitido negociação nos moldes do BDR Nível 3.\nSão as aﬁrmativas:",
        "opcoes": {
            "A": "I, II e IV são falsas.",
            "B": "I, III e IV são verdadeiras.",
            "C": "I, II e III são verdadeiras.",
            "D": "II, III e IV são falsas.",
        },
        "resposta_correta": "C",
        "explicacao": "A afirmativa I está correta ao definir o BDR Nível I como negociado em segmento específico com codificação exclusiva, enquanto as afirmativas II e III corretamente indicam que os BDRs Níveis II e III são admitidos à negociação em mercados organizados. A afirmativa IV está incorreta, pois BDRs não patrocinados são admitidos apenas no nível I, não no nível III."
    },
