    {
        "id": 344,
        "modulo": "Mercado de Capitais",
        "pergunta": "A Resolução CMN Nº 5.008 de 24/3/2022 dispõe sobre a constituição, a\norganização e o funcionamento das sociedades corretoras de títulos e valores mobiliários\n(CTVM) e das sociedades distribuidoras de títulos e valores mobiliários (DTVM). Segundo\nessa resolução, a CTVM e a DTVM:\nI – Seus funcionamentos dependem de autorização do Banco Central do Brasil.\nII – Têm por objeto social intermediar oferta pública e distribuição de títulos e valores\nmobiliários no mercado, podendo também emitir de moeda eletrônica.\nIII – Não podem cobrar de seus comitentes corretagem ou qualquer outra comissão\nreferente  a  negociações  com  determinado  valor  mobiliário  durante  seu  período  de\ndistribuição primária.\nEstá correto o que se aﬁrma em:",
        "opcoes": {
            "A": "I, apenas.",
            "B": "I e II, apenas.",
            "C": "II e III, apenas.",
            "D": "I, II e III.",
        },
        "resposta_correta": "D",
        "explicacao": "A Resolução CMN nº 5.008/2022 estabelece que a constituição e funcionamento das CTVM e DTVM dependem de autorização prévia do Banco Central (art. 2º), e seu objeto social inclui a intermediação de oferta pública e distribuição de valores mobiliários, além da possibilidade de emissão de moeda eletrônica (art. 3º). Ademais, durante a distribuição primária, essas instituições são vedadas de cobrar corretagem ou comissão dos comitentes para evitar conflito de interesses e preservar a transparência no mercado (art. 25). Portanto, todas as assertivas I, II e III estão corretas conforme a regulamentação vigente."
    },
    {
        "id": 345,
        "modulo": "Mercado de Capitais",
        "pergunta": "Considere as aﬁrmativas abaixo:\nI – Risco de crédito está associado ao não pagamento do compromisso pelo seu emissor,\nsendo CDB, debêntures e ações, exemplos de ativos com esse risco.\nII – Risco de liquidez está associado tanto pela diﬁculdade de converter ativo em dinheiro\npor  baixa  demanda  do  mercado,  quanto  por  desvalorização  do  ativo  por  cenário\neconômico desfavorável.\nIII – Risco de mercado pode ser sistemático ou não sistemático, sendo que ambos podem\nser neutralizados pela diversiﬁcação.\nPodemos aﬁrmar que:",
        "opcoes": {
            "A": "I e II são verdadeiras.",
            "B": "I e II são falsas.",
            "C": "II e III são verdadeiras.",
            "D": "Todas são falsas.",
        },
        "resposta_correta": "D",
        "explicacao": "I está incorreta porque ações não possuem risco de crédito, já que representam participação societária e não dívida; apenas CDB e debêntures envolvem esse risco, conforme definido na Resolução CVM 178/23. II está incorreta, pois o risco de liquidez refere-se exclusivamente à dificuldade de venda rápida do ativo sem perda significativa, não incluindo desvalorização causada por cenário econômico, que caracteriza risco de mercado. III está incorreta porque o risco sistemático é inerente ao mercado e não pode ser eliminado por diversificação, enquanto o não sistemático pode; portanto, nem ambos podem ser neutralizados pela diversificação."
    },
    {
        "id": 346,
        "modulo": "Mercado de Capitais",
        "pergunta": "Na administração de uma carteira de títulos de renda ﬁxa, é correto:",
        "opcoes": {
            "A": "Reduzir a Duration da carteira, se o objetivo é apostar na queda da taxa de\njuros.",
            "B": "Reduzir o risco de carteira de títulos preﬁxados ao comprar contratos futuros de\ntaxas de juros.",
            "C": "Reduzir o risco de carteira de títulos preﬁxados ao reduzir a convexidade da\ncarteira.",
            "D": "Reduzir o risco de carteira de títulos preﬁxados ao reduzir a Duration da\ncarteira.",
        },
        "resposta_correta": "D",
        "explicacao": "A Duration mede a sensibilidade do preço de um título de renda fixa às variações nas taxas de juros, conforme definido na Resolução CMN 4.661/2018 e práticas de gestão de risco financeiro. Reduzir a Duration da carteira diminui a exposição à volatilidade dos preços frente a alterações nas taxas, mitigando o risco de mercado. Portanto, para minimizar o risco em títulos prefixados, a estratégia correta é reduzir a Duration da carteira."
    },
    {
        "id": 347,
        "modulo": "Mercado de Capitais",
        "pergunta": "Um  fundo  de  investimento  indexado  a  um  benchmark  apresentou  alta\nvolatilidade nos meses de verão e baixa volatilidade nas demais estações do ano. Dessa\nforma, espera-se que o VaR (Value at Risk) do fundo em uma análise dos retornos dos\núltimos dois anos:",
        "opcoes": {
            "A": "superestima o VaR em todas as estações.",
            "B": "superestima o VaR dos verões e subestima o VaR das demais estações.",
            "C": "subestima o VaR dos verões e superestima o VaR das demais estações.",
            "D": "subestima o VaR em todas as estações.",
        },
        "resposta_correta": "C",
        "explicacao": "A metodologia tradicional de cálculo do VaR baseada em séries históricas assume volatilidade constante, o que não ocorre quando há sazonalidade na volatilidade, como no caso descrito. Assim, ao utilizar dados agregados dos últimos dois anos, o VaR tende a diluir os picos de volatilidade do verão, subestimando o risco nesse período, enquanto superestima o risco nas estações com menor volatilidade. Essa limitação está alinhada com conceitos de heterocedasticidade em séries financeiras, conforme preconizado em práticas recomendadas pela CVM e literatura de risco de mercado."
    },
    {
        "id": 348,
        "modulo": "Mercado de Capitais",
        "pergunta": "A respeito do risco de mercado, é correto aﬁrmar que:",
        "opcoes": {
            "A": "quando uma empresa mantém o Value at Risk (VaR) dentro de níveis aceitáveis\nao longo do tempo, ela estará garantida quando ocorrerem saltos em preços ou\nem taxas de juros do mercado.",
            "B": "a metodologia da simulação de Monte Carlo para o cálculo do Value at Risk\n(VaR) tem a vantagem de ser mais simples de ser utilizada e de permitir a\nestimativa da distribuição de probabilidades das carteiras, quando comparada a\noutras metodologias.",
            "C": "quando um banco de investimentos mantém o Value at Risk (VaR) elevado\nfrequentemente, não há razões para preocupações, desde que ele não tenha\nações negociadas em bolsas.",
            "D": "a métrica de risco conhecida como Value at Risk (VaR) é probabilística e\npossibilita o conhecimento e controle dos riscos.",
        },
        "resposta_correta": "D",
        "explicacao": "A métrica Value at Risk (VaR) é uma medida estatística que estima a máxima perda esperada em um horizonte temporal específico, com um determinado nível de confiança, conforme práticas recomendadas pela Resolução CMN 4.539/16. Por ser probabilística, o VaR permite que instituições financeiras quantifiquem e controlem o risco de mercado de forma sistemática e consistente. Portanto, ele não garante proteção contra eventos extremos (saltos), mas oferece uma base para gestão e adequação de capital frente aos riscos assumidos."
    },
